const icons={briefcase:'<rect x="3" y="7" width="18" height="14" rx="1"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',building:'<path d="M3 21h18M5 21V9h14v12M3 9l9-6 9 6M9 21v-5h6v5M8 12h1m6 0h1"/>',cup:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM17 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2"/>',flask:'<path d="M9 3h6M10 3v7L4 20h16l-6-10V3M7 15h10"/>',leaf:'<path d="M20 3C7 2 2 10 6 16s15 2 14-13ZM4 21 16 8"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',network:'<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="m10 8-4 8m8-8 4 8M8 19h8"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',document:'<path d="M5 3h10l4 4v14H5ZM14 3v5h5M8 12h8M8 16h6"/>'};
let activeFilter='all';const search=document.querySelector('#search');
function render(){const term=search.value.trim().toLowerCase();const selected=resources.filter(r=>(activeFilter==='all'||r.cats.includes(activeFilter))&&`${r.title} ${r.tag} ${r.description}`.toLowerCase().includes(term));document.querySelector('#resource-grid').innerHTML=selected.map(r=>`<article class="resource-card"><div class="card-top"><span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[r.icon]}</svg></span><span class="tag">${r.tag}</span></div><h3>${r.title}</h3><p>${r.description}</p><a href="${r.link}" target="_blank" rel="noopener noreferrer" aria-label="${r.action} (opens in a new tab)">${r.action}<span aria-hidden="true">→</span></a></article>`).join('');document.querySelector('#result-count').textContent=`${selected.length} resource${selected.length===1?'':'s'} to explore · Links open in a new tab`;document.querySelector('#empty').hidden=selected.length>0;document.querySelector('#reset').hidden=activeFilter==='all'&&!term;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===activeFilter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;render()}));document.querySelectorAll('[data-path]').forEach(a=>a.addEventListener('click',()=>{activeFilter=a.dataset.path;search.value='';render()}));search.addEventListener('input',render);document.querySelector('#reset').addEventListener('click',()=>{activeFilter='all';search.value='';render();search.focus()});
const checks=[...document.querySelectorAll('[data-step]')];let saved={};try{saved=JSON.parse(localStorage.getItem('vandal-career-checklist')||'{}')||{};}catch{}checks.forEach(c=>c.checked=!!saved[c.dataset.step]);function updateProgress(){const done=checks.filter(c=>c.checked).length;document.querySelector('#progress-text').textContent=`${done} of 5 complete`;document.querySelector('#progress-bar').style.width=`${done*20}%`;}checks.forEach(c=>c.addEventListener('change',()=>{updateProgress();try{localStorage.setItem('vandal-career-checklist',JSON.stringify(Object.fromEntries(checks.map(c=>[c.dataset.step,c.checked]))));}catch{document.querySelector('#saved-note').textContent='Progress is available for this visit; browser storage is unavailable.'}}));render();updateProgress();
